// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the amount and the recipient index selector (we need at least one param)
    // amount: the raw v[i] that in reference will be multiplied by 1e18, in mutant used as-is
    // recipSeed: used to produce a non-zero address for recipient helper
    function testFuzz_property(uint256 amount, uint256 recipSeed) public {
        // bound recipSeed into small range to index deterministic multiple recipients if needed
        recipSeed = bound(recipSeed, 1, 2);

        // Deploy a helper that will revert if asked to transfer less than a threshold
        // We want a contract that when called with transferFrom(from,to,amt) will revert
        // iff amt < threshold. Set threshold between amount and amount*1e18 when possible.
        // Choose threshold = amount * 1e9 + 1 to keep in uint range; if amount==0, threshold=1.
        uint256 threshold = amount == 0 ? 1 : (amount * 1_000_000_000) + 1;
        ReverterThreshold helper = new ReverterThreshold(threshold);

        // Now craft inputs for c.transfer: one recipient being the helper address, one amount element
        address[] memory tos = new address[](1);
        tos[0] = address(helper);
        uint[] memory vals = new uint[](1);
        vals[0] = amount;

        // The reference multiplies amount by 1e18 before calling helper; mutant does not.
        // We will observe whether c.transfer returns (does not revert) — both versions revert on failed call.
        // Use try/catch to capture boolean success (did not revert).
        bool ok;
        try c.transfer(tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // Property: For all inputs, the reference contract C (the deployed c) will return true
        // whenever the helper does NOT revert on the scaled amount (amount*1e18). Because the helper
        // reverts for amounts < threshold, and amount*1e18 is (almost always) >= threshold when
        // threshold was chosen as ~amount*1e9+1, the reference should succeed for all fuzz inputs.
        // The mutant (which uses unscaled amount) would fail for some inputs where amount < threshold
        // but amount*1e18 >= threshold. To encode the universal property we assert that c.transfer
        // does not revert (ok == true). This holds for the reference for all inputs and the mutant
        // will fail for some inputs (fuzzer will find them).
        assertTrue(ok);
    }
}

// Helper that reverts if the third parameter (uint256 amount) is strictly less than threshold
contract ReverterThreshold {
    uint256 public threshold;
    constructor(uint256 _threshold) {
        threshold = _threshold;
    }
    // accept any calldata; try to decode as transferFrom(address,address,uint256)
    fallback() external payable {
        // decode only if calldata length matches selector + 3 words
        if (msg.data.length >= 4 + 32*3) {
            // skip selector
            bytes memory b = msg.data[4:];
            // abi.decode requires memory bytes; do manual decode via assembly
            address from;
            address to;
            uint256 amt;
            assembly {
                from := mload(add(b, 32))
                to := mload(add(b, 64))
                amt := mload(add(b, 96))
            }
            if (amt < threshold) {
                revert("amt too small");
            }
            // otherwise do nothing (succeed)
        }
        // if calldata unexpected, succeed
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // Helper callee that reverts if the amount passed in transferFrom is less than a threshold
    contract RequireMin {
        uint256 public min;
        constructor(uint256 _min) payable {
            min = _min;
        }
        // mimic transferFrom(address,address,uint256)
        function transferFrom(address, address, uint256 amount) external view returns (bool) {
            require(amount >= min, "amount too small");
            return true;
        }
    }

    function setUp() public {
        c = new C();
    }

    // Fuzz parameters: a single amount threshold and a single v value to put into the array.
    // The fuzzer will search values; we assume reasonable bounds to keep arrays non-empty and avoid overflow.
    function testFuzz_property(uint256 minRequired, uint256 v) public {
        // Keep values in reasonable ranges to avoid trivial over/underflows and keep domain wide.
        minRequired = bound(minRequired, 1, type(uint256).max / 2);
        v = bound(v, 1, type(uint256).max / 2);

        // Deploy helper that requires amounts >= minRequired to succeed.
        // We will pass the helper's address as c.caddress (but c.caddress is immutable in the source and not settable),
        // so instead we rely on the helper existing at the c.caddress expected by C in the provided contract.
        // The reference C uses a hardcoded caddress; to route calls there we must deploy the helper at that exact address.
        // However, deploying at an arbitrary fixed address is not allowed here. Instead, we exploit that the reference
        // C calls caddress.call(...). The provided C has caddress set to a fixed address in its source. To ensure the
        // callee at that address enforces the minimum, we deploy a short proxy contract to that address using CREATE2.

        // The address hardcoded in C source is: 0x1f844685f7Bf86eFcc0e74D8642c54A257111923
        address target = 0x1f844685f7Bf86eFcc0e74D8642c54A257111923;

        // We'll deploy a tiny factory that deploys RequireMin at the desired address via CREATE2 with known salt.
        // The factory uses an init code that constructs RequireMin(minRequired).
        bytes memory requireMinCode = abi.encodePacked(
            // creation code for RequireMin
            type(RequireMin).creationCode,
            abi.encode(minRequired)
        );

        // compute salt so that deployed address equals target
        // deployedAddress = address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), deployer, salt, keccak256(init_code))))));
        // We'll brute-force a salt in a small loop — keep it small to stay cheap in testing. If not found, skip this run.
        bool deployed = false;
        for (uint256 salt = 0; salt < 256; salt++) {
            address computed;
            {
                bytes32 hash = keccak256(abi.encodePacked(bytes1(0xff), address(this), bytes32(salt), keccak256(requireMinCode)));
                computed = address(uint160(uint256(hash)));
            }
            if (computed == target) {
                // deploy via assembly create2
                address addr;
                assembly {
                    addr := create2(0, add(requireMinCode, 0x20), mload(requireMinCode), salt)
                }
                // verify deployment
                if (addr == target) {
                    deployed = true;
                }
                break;
            }
        }

        // If we couldn't deploy the helper at the exact hardcoded address, skip this fuzz case by assuming false
        // This keeps the admissible domain only where we successfully placed the helper. It's still wide because
        // minRequired and v are fuzzed; the loop uses many salts so many cases will find a match in practice.
        vm.assume(deployed);

        // Prepare inputs for transfer: one recipient and one amount
        address[] memory tos = new address[](1);
        uint[] memory vals = new uint[](1);
        // recipient can be any address; use a non-zero fuzzed address from v to keep variety
        tos[0] = address(uint160(uint256(keccak256(abi.encodePacked(v, minRequired)))));
        vals[0] = v;

        // Prank as the expected from address (C requires msg.sender == from). The reference C hardcodes `from` too,
        // so we must call as that address.
        address requiredSender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(requiredSender);

        // Call transfer and capture whether it reverts. The reference multiplies v by 1e18, so if minRequired <= v * 1e18
        // the reference call will succeed (not revert). The mutant sends only v, so for some fuzzed inputs where
        // v < minRequired <= v * 1e18 the mutant will revert but reference succeeds. We assert the reference does not revert.
        bool ok;
        try c.transfer(tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: the reference C should never revert for any admissible input where we've placed the helper.
        assertTrue(ok);
    }
}

