pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Receiver r;

    function setUp() public { c = new C(); r = new Receiver(); }

    // fuzzed params: an array length (n) and a base amount and an index-specific multiplier selector
    // We pass recipient list containing our Receiver and amounts such that for some v the mutant will fail
    function testFuzz_property(uint8 n, uint256 baseAmount, uint256 selector) public {
        // keep arrays in reasonable size but wide
        uint256 len = bound(n, 1, 5);
        // ensure baseAmount is not zero to allow both small and large scaling
        baseAmount = bound(baseAmount, 1, type(uint256).max / 2);

        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(r);
            // construct varied v values using selector to let fuzzer explore small and large v
            vals[i] = (baseAmount >> (uint8((selector + i) % 256) % 64)) + (i == 0 ? 1 : 0);
        }

        // The Receiver expects amounts at least equal to v * 1e18 to succeed; the reference C multiplies by 1e18
        // so calls routed to our Receiver should not revert. We call transfer as the authorized caller.
        address caller = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(caller);

        bool ok;
        try c.transfer(tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: on the correct C (which scales by 1e18), transfer never reverts for any admissible inputs
        // when the callee requires amounts >= v*1e18. The mutant that omits the 1e18 factor can revert for some inputs.
        assertTrue(ok);
    }
}

// Adversarial helper: requires the called amount (last uint arg) to be >= requiredThreshold to succeed.
// It inspects calldata for the uint256 amount passed by C's low-level call and reverts if too small.
contract Receiver {
    // fallback will be invoked by caddress.call(...)
    fallback() external payable {
        // calldata layout: selector(4) + from(32) + to(32) + amount(32)
        // extract amount from calldata (last 32 bytes)
        uint256 amount;
        assembly {
            // calldata offset: 4 + 32 + 32 = 68 -> amount starts at byte 68 (0-indexed), calldataload takes 32-byte aligned word
            amount := calldataload(68)
        }
        // require amount to be at least 1e18 to succeed; this makes the correct contract (which sends v*1e18)
        // always satisfy it for v>=1 while the mutant (sending v) will fail for many v.
        if (amount < 1000000000000000000) {
            revert();
        }
    }
}

